(function(){var b=document.querySelectorAll(".reveal");if("IntersectionObserver"in window){var d=new IntersectionObserver(function(a){a.forEach(function(c){c.isIntersecting&&(c.target.classList.add("visible"),d.unobserve(c.target))})},{threshold:.15,rootMargin:"0px 0px -40px 0px"});b.forEach(function(a){d.observe(a)})}else b.forEach(function(a){a.classList.add("visible")});if(b=document.getElementById("year"))b.textContent=String((new Date).getFullYear())})();
